/bin/bash -lc "python - <<'PY'
import urllib.request
from html.parser import HTMLParser
class P(HTMLParser):
 def __init__(self): super().__init__(); self.on=False; self.depth=0; self.out=[]
 def handle_starttag(self,tag,attrs):
  if ('data-geistdocs-article','body') in attrs: self.on=True
  if self.on:
   self.depth+=1
   if tag in ['p','li','h1','h2','h3','pre']: self.out.append('\\n')
 def handle_endtag(self,tag):
  if self.on:
   self.depth-=1
   if self.depth==0: self.on=False
 def handle_data(self,data):
  if self.on: self.out.append(data)
for slug in ['navigation','prefetch']:
 p=P();p.feed(urllib.request.urlopen('https://nextjs.org/docs/app/api-reference/functions/'+slug,timeout=10).read().decode()); print('\\n###',slug,'###\\n'); print(''.join(p.out)[:13000])
PY"

